INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (0.2, 513044, "", 1, 513, 3, "", "", "", "nop_talk_thinking", 100811);
